static inline int32_t control_take_ends(uint32_t channel, td_wire_msg_t *buf, int32_t *error_code, bool yes) {
  int32_t s = control_take_ends_encode(buf, 0, yes);
  if (s != CROI_OK) return s;
  if ((s = td_wire_call(channel, buf, buf, error_code)) != CROI_OK) return s;
  return control_take_ends_decode_reply(buf);
}

// event (event): decodes it.
static inline int32_t control_event_decode(const td_wire_msg_t *m, pty_ipc_event_t *event) {
  td_wire_reader_t rd, *r = &rd;
  int32_t s = CROI_OK;
  uint64_t v;
  (void)s;
  (void)v;
  td_wire_arena_t *a = NULL;
  (void)a;
  if (td_wire_read_begin(r, m, 8) != CROI_OK) return TD_ERR_PROTOCOL;
  if (td_wire_check_padding(r, 1, 7) != CROI_OK) return TD_ERR_PROTOCOL;
  if (td_wire_load(r, 0, 1, &v) != CROI_OK || !pty_ipc_event_known(v)) return TD_ERR_PROTOCOL;
  (*event) = (pty_ipc_event_t)(uint8_t)v;
  return td_wire_read_end(r);
}

// resized (event): decodes it.
static inline int32_t control_resized_decode(const td_wire_msg_t *m, pty_ipc_window_size_t *size) {
  td_wire_reader_t rd, *r = &rd;
  int32_t s = CROI_OK;
  uint64_t v;
  (void)s;
  (void)v;
  td_wire_arena_t *a = NULL;
  (void)a;
  if (td_wire_read_begin(r, m, 8) != CROI_OK) return TD_ERR_PROTOCOL;
  if ((s = pty_ipc_window_size_decode(r, 0, a, &((*size)))) != CROI_OK) return s;
  return td_wire_read_end(r);
}

